// ============================================================
// SEED FUNCTIONS
// ============================================================

async function clearExistingData(): Promise<void> {
  console.log('Step 1: Clearing existing data...');

  const { error: e1 } = await supabase
    .from('students')
    .delete()
    .neq('id', '00000000-0000-0000-0000-000000000000');
  if (e1) console.log(`  Warning clearing students: ${e1.message}`);

  const { error: e2 } = await supabase
    .from('staff')
    .delete()
    .neq('id', '00000000-0000-0000-0000-000000000000');
  if (e2) console.log(`  Warning clearing staff: ${e2.message}`);

  console.log('  Existing data cleared.');
}

async function seedStudents(): Promise<number> {
  console.log(`\nStep 2: Seeding ${realStudents.length} students...`);

  const dbStudents = realStudents.map((s) => ({
    sr_no: s.sr_no,
    full_name: s.full_name,
    standard: s.standard,
    date_of_birth: s.date_of_birth,
    blood_group: s.blood_group,
    apaar_id: s.apaar_id,
    mobile_number: s.mobile_number,
    guardian_name: s.guardian_name,
    village: s.village,
    taluka: s.taluka,
    district: s.district,
    pincode: s.pincode,
    guardian_mobile: s.guardian_mobile,
    guardian_relation: s.guardian_relation,
    status: 'Enrolled',
  }));

  let inserted = 0;
  for (let i = 0; i < dbStudents.length; i += BATCH_SIZE) {
    const batch = dbStudents.slice(i, i + BATCH_SIZE);
    const { error } = await supabase.from('students').insert(batch);
    if (error) {
      console.error(`  Error inserting students batch ${Math.floor(i / BATCH_SIZE) + 1}: ${error.message}`);
      continue;
    }
    inserted += batch.length;
    const batchNum = Math.floor(i / BATCH_SIZE) + 1;
    const totalBatches = Math.ceil(dbStudents.length / BATCH_SIZE);
    console.log(`  Batch ${batchNum}/${totalBatches} inserted (${inserted} total)`);
  }

  return inserted;
}

async function seedStaff(): Promise<number> {
  console.log(`\nStep 3: Seeding ${realStaff.length} staff members...`);

  const dbStaff = realStaff.map((s) => ({
    full_name: s.full_name,
    designation: s.designation,
    department: s.department,
    mobile_number: s.mobile_number,
    email: s.email,
    joining_date: s.joining_date,
    status: 'active',
  }));

  const { error } = await supabase.from('staff').insert(dbStaff);
  if (error) {
    console.error(`  Error inserting staff: ${error.message}`);
    return 0;
  }

  console.log(`  Inserted ${dbStaff.length} staff members.`);
  return dbStaff.length;
}

async function verifyCounts(): Promise<void> {
  console.log('\nStep 4: Verifying data...');

  const { count: studentCount } = await supabase
    .from('students')
    .select('*', { count: 'exact', head: true });
  const { count: staffCount } = await supabase
    .from('staff')
    .select('*', { count: 'exact', head: true });

  console.log(`  Students in database: ${studentCount ?? 0}`);
  console.log(`  Staff in database: ${staffCount ?? 0}`);

  if (studentCount !== realStudents.length) {
    console.warn(`  WARNING: Expected ${realStudents.length} students, got ${studentCount}`);
  }
  if (staffCount !== realStaff.length) {
    console.warn(`  WARNING: Expected ${realStaff.length} staff, got ${staffCount}`);
  }
}

async function main() {
  console.log('==========================================================');
  console.log(' Ashram Shala Pathraj - Real Data Seed Script');
  console.log(' शासकीय माध्यमिक व उच्च माध्यमिक आश्रमशाळा पाथरज');
  console.log('==========================================================');
  console.log(`Supabase URL: ${SUPABASE_URL}`);
  console.log(`Total students to seed: ${realStudents.length}`);
  console.log(`Total staff to seed: ${realStaff.length}`);
  console.log('');

  // Step 1: Clear existing data
  await clearExistingData();

  // Step 2: Seed students
  const studentCount = await seedStudents();

  // Step 3: Seed staff
  const staffCount = await seedStaff();

  // Step 4: Verify
  await verifyCounts();

  console.log('\n==========================================================');
  console.log(` Seed Complete!`);
  console.log(` Inserted: ${studentCount} students, ${staffCount} staff`);
  console.log('==========================================================');
}

main().catch((err) => {
  console.error('Seed failed:', err);
  process.exit(1);
});
